#!/usr/bin/env python3
import os, zipfile, shutil

OUTDIR = os.path.abspath("v7_full_engine")
ZIPOUT = os.path.abspath("v7_full_engine.zip")

FILES = {'README.md': '# Syntax-Directed Editor — v7\n\nRun GUI: python demo_gui_v7.py\nRun Bench: python bench_typing.py\n', 'sde/__init__.py': '# package marker\n', 'sde/astnodes.py': 'from __future__ import annotations\nfrom dataclasses import dataclass, field\nfrom typing import List, Optional, Any\n\n@dataclass\nclass ASTNode:\n    kind: str\n    children: List["ASTNode"] = field(default_factory=list)\n    value: Any = None\n    start: int = 0\n    end: int = 0\n    parent: Optional["ASTNode"] = None\n    thread_prev: Optional["ASTNode"] = None\n    reused: bool = False\n    disposable: bool = False\n\n    def adopt(self, child: "ASTNode"):\n        child.parent = self\n        self.children.append(child)\n\n    def preorder(self):\n        yield self\n        for c in self.children:\n            yield from c.preorder()\n\n    def rebuild_threads(self):\n        prev = None\n        for n in self.preorder():\n            n.thread_prev = prev\n            prev = n\n\n    def relabel_spans_up(self):\n        n = self\n        while n:\n            if n.children:\n                n.start = n.children[0].start\n                n.end = n.children[-1].end\n            n = n.parent\n\ndef make_leaf(kind: str, value, start: int, end: int) -> ASTNode:\n    return ASTNode(kind=kind, value=value, start=start, end=end)\n\ndef make_node(kind: str, children: List[ASTNode]) -> ASTNode:\n    n = ASTNode(kind=kind, children=children)\n    for c in children:\n        c.parent = n\n    if children:\n        n.start = children[0].start\n        n.end = children[-1].end\n    return n\n', 'sde/lexer.py': 'from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import List\n\n@dataclass\nclass Token:\n    type: str\n    value: str\n    start: int\n    end: int\n\ndef lex(src: str) -> List[Token]:\n    i, n = 0, len(src)\n    out: List[Token] = []\n    while i < n:\n        ch = src[i]\n        if ch.isspace():\n            i += 1; continue\n        if ch.isdigit():\n            j = i\n            while j < n and src[j].isdigit(): j += 1\n            out.append(Token("NUM", src[i:j], i, j))\n            i = j; continue\n        if ch.isalpha() or ch == "_":\n            j = i\n            while j < n and (src[j].isalnum() or src[j] == "_"): j += 1\n            out.append(Token("ID", src[i:j], i, j))\n            i = j; continue\n        if ch in "+*()":\n            typ = {"+":"PLUS","*":"STAR","(":"LP",")":"RP"}[ch]\n            out.append(Token(typ, ch, i, i+1))\n            i += 1; continue\n        out.append(Token("UNK", ch, i, i+1)); i += 1\n    out.append(Token("EOF","", n, n))\n    return out\n', 'sde/attrib.py': 'from __future__ import annotations\nfrom collections import deque\nfrom typing import Dict\nfrom .astnodes import ASTNode\n\ndef compute_value(root: ASTNode, env: Dict[str,int]|None=None):\n    env = env or {}\n    q = deque(n for n in root.preorder())\n    while q:\n        n = q.popleft()\n        old = getattr(n, "_val", None)\n        new = eval_node(n, env)\n        if new != old:\n            n._val = new\n            if n.parent: q.append(n.parent)\n    return getattr(root.children[0], "_val", None) if root.children else None\n\ndef eval_node(n: ASTNode, env: Dict[str,int]):\n    if n.kind == "NUM": return int(n.value)\n    if n.kind == "ID": return env.get(n.value, 0)\n    if n.kind == "GROUP":\n        return getattr(n.children[1], "_val", None) if len(n.children) >= 2 else None\n    if n.kind == "BINOP":\n        left, op, right = n.children\n        lv = getattr(left, "_val", None); rv = getattr(right, "_val", None)\n        if lv is None or rv is None: return None\n        return lv + rv if op.value == "+" else (lv * rv if op.value == "*" else None)\n    if n.kind == "ERROR": return None\n    return getattr(n.children[0], "_val", None) if n.children else None\n', 'sde/ttlr.py': 'from __future__ import annotations\nfrom typing import List, Tuple, Dict\nfrom .lexer import Token\nfrom .astnodes import ASTNode, make_leaf, make_node\n\nACTION: Dict[int, Dict[str, Tuple[str, int]]] = {\n    0: {\'LP\':(\'s\',4), \'ID\':(\'s\',5), \'NUM\':(\'s\',6)},\n    1: {\'PLUS\':(\'s\',7), \'EOF\':(\'acc\',0)},\n    2: {\'PLUS\':(\'r\',2), \'STAR\':(\'s\',8), \'RP\':(\'r\',2), \'EOF\':(\'r\',2)},\n    3: {\'PLUS\':(\'r\',4), \'STAR\':(\'r\',4), \'RP\':(\'r\',4), \'EOF\':(\'r\',4)},\n    4: {\'LP\':(\'s\',4), \'ID\':(\'s\',5), \'NUM\':(\'s\',6)},\n    5: {\'PLUS\':(\'r\',7), \'STAR\':(\'r\',7), \'RP\':(\'r\',7), \'EOF\':(\'r\',7)},\n    6: {\'PLUS\':(\'r\',6), \'STAR\':(\'r\',6), \'RP\':(\'r\',6), \'EOF\':(\'r\',6)},\n    7: {\'LP\':(\'s\',4), \'ID\':(\'s\',5), \'NUM\':(\'s\',6)},\n    8: {\'LP\':(\'s\',4), \'ID\':(\'s\',5), \'NUM\':(\'s\',6)},\n    9: {\'PLUS\':(\'s\',7), \'RP\':(\'s\',12)},\n    10:{\'PLUS\':(\'r\',1), \'STAR\':(\'s\',8), \'RP\':(\'r\',1), \'EOF\':(\'r\',1)},\n    11:{\'PLUS\':(\'r\',3), \'STAR\':(\'r\',3), \'RP\':(\'r\',3), \'EOF\':(\'r\',3)},\n    12:{\'PLUS\':(\'r\',5), \'STAR\':(\'r\',5), \'RP\':(\'r\',5), \'EOF\':(\'r\',5)},\n}\nGOTO: Dict[int, Dict[str, int]] = {\n    0: {\'E\':1, \'T\':2, \'F\':3},\n    4: {\'E\':9, \'T\':2, \'F\':3},\n    7: {\'T\':10, \'F\':3},\n    8: {\'F\':11},\n    9: {}, 10:{}, 11:{}, 12:{}\n}\nSYNC = {\'PLUS\',\'STAR\',\'RP\',\'EOF\'}\n\ndef reduce_build(rule: int, stack: List[Tuple[int, ASTNode]]):\n    if rule == 1:\n        nodeT = stack[-1][1]; nodePLUS = stack[-2][1]; nodeE = stack[-3][1]\n        binop = make_node("BINOP", [nodeE, make_leaf("PLUS", "+", nodePLUS.start, nodePLUS.end), nodeT])\n        return "E", binop, 3\n    if rule == 2: return "E", stack[-1][1], 1\n    if rule == 3:\n        nodeF = stack[-1][1]; nodeSTAR = stack[-2][1]; nodeT = stack[-3][1]\n        binop = make_node("BINOP", [nodeT, make_leaf("STAR", "*", nodeSTAR.start, nodeSTAR.end), nodeF])\n        return "T", binop, 3\n    if rule == 4: return "T", stack[-1][1], 1\n    if rule == 5:\n        nodeRP = stack[-1][1]; nodeE = stack[-2][1]; nodeLP = stack[-3][1]\n        group = make_node("GROUP", [make_leaf("LP","(", nodeLP.start, nodeLP.end), nodeE, make_leaf("RP",")", nodeRP.start, nodeRP.end)])\n        return "F", group, 3\n    if rule == 6: return "F", stack[-1][1], 1\n    if rule == 7: return "F", stack[-1][1], 1\n    raise ValueError(rule)\n\nclass LRParser:\n    def __init__(self, tokens: List[Token]):\n        self.tokens = tokens\n        self.shift_nodes: List[ASTNode] = []\n        self.recovery_log: List[str] = []\n\n    def expect_rp_state(self, state:int)->bool:\n        return state in (9,)\n\n    def parse(self) -> ASTNode:\n        stack: List[Tuple[int, ASTNode]] = [(0, ASTNode(kind=\'^\', start=0, end=0))]\n        i = 0\n        while True:\n            state = stack[-1][0]\n            t = self.tokens[i]\n            act = ACTION.get(state, {}).get(t.type)\n\n            if act is None:\n                if (t.type in (\'EOF\',\'PLUS\',\'RP\')) and self.expect_rp_state(state):\n                    self.recovery_log.append(f"synthesize RP at {t.start}")\n                    self.tokens.insert(i, Token(\'RP\', \')\', t.start, t.start))\n                    continue\n                if t.type not in SYNC:\n                    self.recovery_log.append(f"skip {t.type} [{t.start},{t.end})")\n                    err = ASTNode(kind=\'ERROR\', start=t.start, end=t.end, disposable=True)\n                    self.shift_nodes.append(err); stack.append((state, err)); i += 1; continue\n                self.recovery_log.append(f"consume sync {t.type} as ERROR")\n                err = ASTNode(kind=\'ERROR\', start=t.start, end=t.end, disposable=True)\n                self.shift_nodes.append(err); stack.append((state, err)); i += 1; continue\n\n            kind, arg = act\n            if kind == \'s\':\n                val = int(t.value) if t.type==\'NUM\' else t.value or t.type\n                node = ASTNode(kind=t.type, value=val, start=t.start, end=t.end)\n                self.shift_nodes.append(node)\n                stack.append((arg, node))\n                i += 1\n            elif kind == \'r\':\n                lhs, node, popn = reduce_build(arg, stack)\n                for _ in range(popn): stack.pop()\n                state2 = stack[-1][0]\n                goto = GOTO.get(state2, {}).get(lhs)\n                if goto is None:\n                    err = ASTNode(kind=\'ERROR\', start=node.start, end=node.end, disposable=True)\n                    stack.append((state2, err)); continue\n                stack.append((goto, node))\n            elif kind == \'acc\':\n                root = make_node(\'ROOT\', [stack[-1][1]])\n                setattr(root, "_shift_nodes", self.shift_nodes)\n                setattr(root, "_recovery_log", self.recovery_log)\n                root.rebuild_threads()\n                return root\n\n    def parse_fragment(self) -> ASTNode:\n        r = self.parse()\n        return r.children[0] if r.children else r\n', 'sde/incremental.py': 'from __future__ import annotations\nfrom typing import Tuple, List\nfrom bisect import bisect_left\nfrom .lexer import lex, Token\nfrom .ttlr import LRParser\nfrom .astnodes import ASTNode\n\n_metrics = {"climb_total":0,"climb_count":0,"fallbacks":0,"max_depth":0}\n\ndef parse_text(src: str) -> ASTNode:\n    return LRParser(lex(src)).parse()\n\ndef _leaf_positions(root: ASTNode):\n    leaves = getattr(root, "_shift_nodes", None)\n    if not leaves:\n        leaves = [n for n in root.preorder() if not n.children]\n    return [n.start for n in leaves], leaves\n\ndef _expand_to_token_boundaries(tokens: List[Token], s: int, e: int) -> tuple[int,int]:\n    core = tokens[:-1] if tokens and tokens[-1].type == "EOF" else tokens\n    left, right = s, e\n    for t in core:\n        if t.start <= s < t.end or t.end == s:\n            left = t.start; break\n        if s < t.start:\n            left = t.start; break\n    for t in reversed(core):\n        if t.start < e <= t.end or t.start == e:\n            right = t.end; break\n        if e > t.end:\n            right = t.end; break\n    return max(0,left), max(left,right)\n\ndef fast_covering(root: ASTNode, start: int, end: int, budget:int):\n    starts, leaves = _leaf_positions(root)\n    if not leaves: return root, False, 0\n    idx = bisect_left(starts, start)\n    cand = leaves[min(idx, len(leaves)-1)]\n    depth = 0; n = cand\n    while n and not (n.start <= start and end <= n.end):\n        depth += 1\n        if depth > budget:\n            _metrics["fallbacks"] += 1\n            return root, True, depth\n        n = n.parent\n    _metrics["climb_total"] += depth; _metrics["climb_count"] += 1; _metrics["max_depth"] = max(_metrics["max_depth"], depth)\n    return (n or root), False, depth\n\ndef replace_child(parent: ASTNode, old_child: ASTNode, new_child: ASTNode):\n    for i, c in enumerate(parent.children):\n        if c is old_child:\n            parent.children[i] = new_child; new_child.parent = parent; break\n    parent.relabel_spans_up()\n\ndef incremental_edit(root: ASTNode, src_before: str, edit: Tuple[int,int,str], budget:int=5):\n    s, e, text = edit\n    new_src = src_before[:s] + text + src_before[e:]\n    cover, fallback, _ = fast_covering(root, s, e, budget)\n    if fallback:\n        return parse_text(new_src), new_src\n    toks = lex(new_src)\n    delta = len(text) - (e - s)\n    new_cover_end = cover.end + delta if cover.end >= e else cover.end\n    slice_start, slice_end = _expand_to_token_boundaries(toks, min(cover.start, s), max(new_cover_end, s+len(text)))\n    frag_tokens = [Token(t.type, t.value, t.start, t.end) for t in toks if t.start >= slice_start and t.end <= slice_end]\n    frag = LRParser(frag_tokens + [Token("EOF","",slice_end,slice_end)]).parse_fragment()\n    parent = cover.parent or root\n    replace_child(parent, cover, frag)\n    while parent.parent: parent = parent.parent\n    root = parent\n    while root.parent: root = root.parent\n    if root.kind != "ROOT": root = parse_text(new_src)\n    else: root.rebuild_threads()\n    return root, new_src\n\ndef metrics(): return dict(_metrics)\n', 'demo_gui_v7.py': 'import tkinter as tk\nfrom tkinter import ttk\nfrom sde.incremental import parse_text, incremental_edit, metrics\nfrom sde.attrib import compute_value\n\nclass SDEGui(tk.Tk):\n    def __init__(self):\n        super().__init__()\n        self.title("SDE v7 — demo")\n        self.geometry("1000x600")\n\n        paned = ttk.Panedwindow(self, orient=tk.HORIZONTAL); paned.pack(fill="both", expand=True)\n\n        left = ttk.Frame(paned); left.columnconfigure(0, weight=1); left.rowconfigure(0, weight=1)\n        self.text = tk.Text(left, wrap="none", font=("Consolas", 12))\n        self.text.grid(row=0, column=0, sticky="nsew")\n        self.text.insert("1.0", "(12+abc)*(3+4)")\n        paned.add(left, weight=3)\n\n        right = ttk.Frame(paned); right.columnconfigure(0, weight=1); right.rowconfigure(0, weight=1)\n        self.tree = ttk.Treeview(right, columns=("span","val"), show="tree headings")\n        self.tree.heading("#0", text="Node")\n        self.tree.heading("span", text="[start,end)")\n        self.tree.heading("val", text="value")\n        self.tree.grid(row=0, column=0, sticky="nsew")\n        paned.add(right, weight=2)\n\n        self.status = tk.StringVar(value="Ready")\n        ttk.Label(self, textvariable=self.status, anchor="w").pack(fill="x")\n\n        self.src = self.text.get("1.0", "end-1c")\n        self.root = parse_text(self.src)\n        compute_value(self.root)\n        self.refresh_tree()\n        self.text.bind("<KeyRelease>", self.on_key)\n\n    def on_key(self, event):\n        new_src = self.text.get("1.0", "end-1c")\n        if new_src == self.src: return\n        s=0; old,new=self.src,new_src\n        while s < len(old) and s < len(new) and old[s]==new[s]: s+=1\n        e_old,e_new=len(old),len(new)\n        while e_old> s and e_new> s and old[e_old-1]==new[e_new-1]: e_old-=1; e_new-=1\n        text=new[s:e_new]\n        try:\n            self.root,self.src=incremental_edit(self.root,self.src,(s,e_old,text),budget=5)\n            val=compute_value(self.root)\n            self.status.set(f"value={val}  fallbacks={metrics()[\'fallbacks\']}")\n            self.refresh_tree()\n        except Exception as ex:\n            self.status.set(f"Error: {ex}")\n\n    def refresh_tree(self):\n        self.tree.delete(*self.tree.get_children())\n        def add(node, parent=""):\n            span = f"[{node.start},{node.end})"\n            val = getattr(node, "_val", "")\n            item = self.tree.insert(parent, "end", text=node.kind, values=(span, val))\n            for c in node.children:\n                add(c, item)\n        add(self.root)\n\nif __name__ == "__main__":\n    SDEGui().mainloop()\n', 'bench_typing.py': "import time, statistics, random\nfrom sde.incremental import parse_text, incremental_edit\n\ndef random_edit(src):\n    if not src: return (0,0,'1')\n    kind = random.choice(['insert','delete','replace'])\n    pos = random.randint(0, len(src))\n    if kind == 'insert':\n        txt = random.choice(['+','*','(',')',str(random.randint(0,9)),'x','y'])\n        return (pos,pos,txt)\n    if kind == 'delete':\n        if pos == len(src): pos = max(0,pos-1)\n        return (pos, min(len(src),pos+1), '')\n    end = min(len(src), pos+random.randint(1,2))\n    txt = random.choice([str(random.randint(0,9)),'+','*','(',')','z'])\n    return (pos,end,txt)\n\ndef run(n=200, seed=0, budget=5):\n    random.seed(seed)\n    src = '1+2*3'\n    root = parse_text(src)\n    times = []\n    for _ in range(n):\n        edit = random_edit(src)\n        t0 = time.perf_counter()\n        root, src = incremental_edit(root, src, edit, budget=budget)\n        times.append((time.perf_counter()-t0)*1000.0)\n    p50 = statistics.median(times)\n    p95 = statistics.quantile(times,0.95)\n    print(f'Edits={n} budget={budget} p50={p50:.2f}ms p95={p95:.2f}ms')\n\nif __name__ == '__main__':\n    run()\n"}

def w(rel, content):
    path = os.path.join(OUTDIR, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)

def main():
    if os.path.exists(OUTDIR):
        shutil.rmtree(OUTDIR)
    os.makedirs(OUTDIR, exist_ok=True)
    for rel, content in FILES.items():
        w(rel, content)

    if os.path.exists(ZIPOUT):
        os.remove(ZIPOUT)
    with zipfile.ZipFile(ZIPOUT, "w", zipfile.ZIP_DEFLATED) as z:
        for dirpath, _, filenames in os.walk(OUTDIR):
            for fn in filenames:
                full = os.path.join(dirpath, fn)
                arc = os.path.relpath(full, OUTDIR)
                z.write(full, arcname=f"v7_full_engine/{arc}")
    print("Wrote:", ZIPOUT)

if __name__ == "__main__":
    main()
